import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";
import type { ClientEntitlements } from "@/lib/entitlements";
// JSON-safe contract shared by server reporting and advisory client displays.
export type QuotaAllowance = {
  sent: number;
  reserved: number;
  used: number;
  limit: number;
  remaining: number;
  startsAt: string | null;
  endsAt: string | null;
  resetsAt: string | null;
};
export type QuotaSnapshot = {
  notices?: {
    id: string;
    campaignIdSnapshot: string;
    reasonCode: string;
    cancelledCount: number;
    createdAt: string;
  }[];
  accessVersion?: string;
} & (
  | { mode: "legacy"; used: number; limit: typeof DAILY_EMAIL_LIMIT }
  | {
      mode: "gated";
      entitlements: ClientEntitlements;
      used: number;
      limit: number;
      plan: "FREE" | "PAID";
      daily: QuotaAllowance;
      monthly: QuotaAllowance;
      sendingAllowed: boolean;
      pauseReason: string | null;
    }
);
